import{_ as t}from"./chunks/thumb-06.CdSJlpm1.js";import{_ as o,H as a,f as l,i as r}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"Cline 使用教程：VS Code 开源 Agent 与 API 配置","description":"","frontmatter":{"title":"Cline 使用教程：VS Code 开源 Agent 与 API 配置","date":"2026-05-22T00:00:00.000Z","category":"技术","tags":["AI","Cline","VS Code","教程"],"excerpt":"开源 VS Code 扩展 Cline：接 Anthropic/OpenAI/国产模型 API，Plan/Act 模式与 MCP 扩展。"},"headers":[],"relativePath":"posts/技术/cline-vscode-agent-tutorial.md","filePath":"posts/技术/cline-vscode-agent-tutorial.md"}'),i={name:"posts/技术/cline-vscode-agent-tutorial.md"};function n(d,e,s,c,h,p){return a(),l("div",null,[...e[0]||(e[0]=[r('<img src="'+t+'" alt="配图" class="article-banner" loading="lazy"><h1 id="cline-使用教程" tabindex="-1">Cline 使用教程 <a class="header-anchor" href="#cline-使用教程" aria-label="Permalink to &quot;Cline 使用教程&quot;">​</a></h1><p><a href="https://github.com/cline/cline" target="_blank" rel="noreferrer">Cline</a>（前身 Clawd / Claude Dev）是 VS Code 上的<strong>开源 AI 编程 Agent</strong> 扩展：保留你现有编辑器与插件，通过配置 <strong>API Key</strong> 或兼容端点调用 Claude、GPT、Gemini、DeepSeek、GLM 等模型。</p><p>适合：不想换 Cursor/Windsurf，但想要<strong>可插拔模型</strong>与<strong>透明开源</strong>的开发者。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li>VS Code 扩展市场搜索 <strong>Cline</strong>，安装。</li><li>侧边栏出现 Cline 图标，打开设置（Settings）。</li><li>选择 <strong>API Provider</strong>（Anthropic / OpenAI / OpenRouter / 自定义 Base URL 等）。</li><li>填入 API Key 或 OAuth（视提供商而定）。</li><li>选择模型 ID（如 <code>claude-sonnet-4</code>、<code>gpt-4o</code> 等，以账户可用为准）。</li></ol><h2 id="plan-与-act-模式" tabindex="-1">Plan 与 Act 模式 <a class="header-anchor" href="#plan-与-act-模式" aria-label="Permalink to &quot;Plan 与 Act 模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>行为</th></tr></thead><tbody><tr><td><strong>Plan</strong></td><td>先出步骤与将改的文件，等你确认再动手</td></tr><tr><td><strong>Act</strong></td><td>直接读文件、编辑、跑终端命令</td></tr></tbody></table><p>建议默认 <strong>Plan</strong>，熟悉仓库后再对简单任务用 Act。</p><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><ol><li>在 Cline 输入任务，附带 <code>@</code> 文件（如 <code>@src/main.dart</code>）。</li><li>审阅 Plan 里的文件列表与风险点。</li><li>批准执行，观察终端输出与 diff。</li><li>本地跑测试，失败则把日志贴回 Cline 继续迭代。</li><li>提交前自己 Review 安全相关改动（网络、鉴权、路径遍历）。</li></ol><h2 id="mcp-model-context-protocol" tabindex="-1">MCP（Model Context Protocol） <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP（Model Context Protocol）&quot;">​</a></h2><p>Cline 支持挂载 MCP Server，例如：</p><ul><li>文件系统、GitHub、数据库只读查询</li><li>团队内部文档检索</li></ul><p>在设置里添加 MCP 配置 JSON，可让 Agent 拉取<strong>实时上下文</strong>，减少胡编。</p><h2 id="与-roo-code、kilo-code-的关系" tabindex="-1">与 Roo Code、Kilo Code 的关系 <a class="header-anchor" href="#与-roo-code、kilo-code-的关系" aria-label="Permalink to &quot;与 Roo Code、Kilo Code 的关系&quot;">​</a></h2><p>同属 VS Code Agent 生态，UI 与配置不同。若已用 Roo Code，迁移到 Cline 主要是<strong>习惯与预设</strong>差异，核心仍是「API + 工具调用」。</p><h2 id="成本与国产模型" tabindex="-1">成本与国产模型 <a class="header-anchor" href="#成本与国产模型" aria-label="Permalink to &quot;成本与国产模型&quot;">​</a></h2><ul><li>自带 Key：按各平台 API 单价计费，适合控制用量。</li><li>智谱 GLM Coding Plan 等套餐声明支持 Cline / Claude Code 协议兼容，见收藏区 GLM 教程。</li><li>可用 CC Switch 统一管理多端点（可选）。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：和 GitHub Copilot 一起装？</strong><br> A：可以，但避免同时开两套 Agent 自动改同一文件；Copilot 做补全，Cline 做任务。</p><p><strong>Q：命令执行安全吗？</strong><br> A：生产仓库关闭危险命令自动批准；对 <code>rm -rf</code>、<code>curl | sh</code> 保持警惕。</p><p><strong>Q：Roo Code 还要学吗？</strong><br> A：二选一即可，原理相通；团队统一工具链更重要。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>收藏区：<a href="/posts/收藏/appark-cc-switch-download-tutorial.html">CC Switch 配置多 Agent</a></li></ul><hr><p><em>扩展版本与 Provider 列表以 Cline GitHub 为准。</em></p>',27)])])}const P=o(i,[["render",n]]);export{u as __pageData,P as default};
